import { TestBed } from '@angular/core/testing';

import { AuthService } from './auth.service';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';

describe('AuthService', () => {
  let service: AuthService;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule], // Mock HTTP requests
      providers: [AuthService]
    });
    service = TestBed.inject(AuthService);
    httpMock = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpMock.verify(); // Ensure no open requests remain
  });

  it('should login and return a token', () => {
    const mockToken = { token: 'fake-jwt-token' };

    service.login('test@example.com', 'password').subscribe(response => {
      expect(response).toEqual(mockToken); // Ensure the response is correct
      expect(localStorage.getItem('authToken')).toBe(mockToken.token); // Ensure token is saved
    });

    // Mock request and respond with a fake token
    const req = httpMock.expectOne('http://localhost:8080/api/auth/login');
    expect(req.request.method).toBe('POST');
    req.flush(mockToken);
  });

  it('should logout and remove token', () => {
    spyOn(localStorage, 'removeItem');

    service.logout();
    expect(localStorage.removeItem).toHaveBeenCalledWith('authToken');
  });
});
